+	const sec = (s % 60).toString().padStart(2, "0");
+	return `${m}:${sec}`;
+});
+
+function savePainting() {
+	if (!store.canvasDataURL) return;
+	const a = document.createElement("a");
+	a.href = store.canvasDataURL;
+	a.download = `speeddraw.png`;
